<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { resourceApi } from '@/api/resource'
import { useAuthStore } from '@/stores/auth'
const auth=useAuthStore();const rows=ref<any[]>([]);const total=ref(0);const loading=ref(false);const dialog=ref(false);const editId=ref<number|null>(null);const options=ref<any>({regions:[],carriers:[]});const query=reactive({page:1,size:20,keyword:'',status:''});const form=reactive<any>({supplierCode:'',supplierName:'',contactName:'',contactPhone:'',apiEndpoint:'',authTypeCode:'TOKEN',apiAccount:'',secret:'',regionCodes:[],carrierCodes:[],fetchMode:'MANUAL'})
async function load(){loading.value=true;try{const d=(await resourceApi.suppliers(query)).data.data;rows.value=d.items;total.value=d.total}finally{loading.value=false}}
function reset(){Object.assign(form,{supplierCode:'',supplierName:'',contactName:'',contactPhone:'',apiEndpoint:'',authTypeCode:'TOKEN',apiAccount:'',secret:'',regionCodes:[],carrierCodes:[],fetchMode:'MANUAL'})}function add(){editId.value=null;reset();dialog.value=true}function edit(r:any){editId.value=r.id;Object.assign(form,{supplierCode:r.supplier_code,supplierName:r.supplier_name,contactName:r.contact_name||'',contactPhone:r.contact_phone||'',apiEndpoint:r.api_endpoint,authTypeCode:r.auth_type_code,apiAccount:r.api_account||'',secret:'',regionCodes:r.region_codes||[],carrierCodes:r.carrier_codes||[],fetchMode:r.fetch_mode});dialog.value=true}
async function save(){if(!form.supplierCode||!form.supplierName||!form.apiEndpoint||!form.authTypeCode){ElMessage.warning('请填写必填项');return}editId.value?await resourceApi.updateSupplier(editId.value,form):await resourceApi.createSupplier(form);dialog.value=false;ElMessage.success('供应商配置已保存');await load()}
async function action(r:any,type:'test'|'enable'|'pause'|'disable'|'sync'){const labels={test:'测试配置',enable:'启用',pause:'暂停',disable:'停用',sync:'获取外部资源'};const {value}=await ElMessageBox.prompt(`请输入${labels[type]}原因`,labels[type],{inputValidator:v=>!!String(v||'').trim()||'必须填写原因'});if(type==='test'){const d=(await resourceApi.testSupplier(r.id,String(value))).data.data;ElMessage.info(d.message)}else if(type==='enable')await resourceApi.enableSupplier(r.id,String(value));else if(type==='pause')await resourceApi.pauseSupplier(r.id,String(value));else if(type==='disable')await resourceApi.disableSupplier(r.id,String(value));else{const d=(await resourceApi.createSync({sourceType:'SUPPLIER',supplierId:r.id,targetPoolId:null,reason:String(value)})).data.data;ElMessage.success(`外部资源同步完成，任务ID ${d.taskId}`)}await load()}
onMounted(async()=>{options.value=(await resourceApi.options()).data.data;await load()})
</script><template><div class="page"><div class="head"><div><h2>外部供应商</h2><p>只保存供应商接入配置和加密凭证；实际接口协议通过 ResourceAdapter 对接，供应商密钥不会回显。</p></div><el-button v-if="auth.hasPermission('resource:supplier:write')" type="primary" @click="add">新增供应商</el-button></div><el-card shadow="never"><div class="filters"><el-input v-model="query.keyword" placeholder="编码/名称" clearable/><el-select v-model="query.status" placeholder="状态" clearable><el-option label="启用" value="ACTIVE"/><el-option label="暂停" value="PAUSED"/><el-option label="停用" value="DISABLED"/></el-select><el-button type="primary" @click="query.page=1;load()">查询</el-button></div><el-table :data="rows" v-loading="loading" stripe><el-table-column prop="supplier_code" label="编码" width="140"/><el-table-column prop="supplier_name" label="供应商" min-width="160"/><el-table-column prop="api_endpoint" label="接口地址" min-width="220" show-overflow-tooltip/><el-table-column prop="auth_type_code" label="认证" width="100"/><el-table-column prop="fetch_mode" label="获取模式" width="100"/><el-table-column label="密钥" width="85"><template #default="s"><el-tag :type="s.row.secret_configured?'success':'info'">{{s.row.secret_configured?'已配置':'未配置'}}</el-tag></template></el-table-column><el-table-column prop="interface_status" label="接口状态" width="100"/><el-table-column prop="status" label="状态" width="90"/><el-table-column label="操作" min-width="280" fixed="right"><template #default="s"><el-button v-if="auth.hasPermission('resource:supplier:write')" link @click="edit(s.row)">编辑</el-button><el-button v-if="auth.hasPermission('resource:supplier:test')" link type="primary" @click="action(s.row,'test')">测试</el-button><el-button v-if="auth.hasPermission('resource:sync')&&s.row.status==='ACTIVE'" link type="primary" @click="action(s.row,'sync')">获取资源</el-button><el-button v-if="auth.hasPermission('resource:supplier:status')&&s.row.status==='PAUSED'" link type="success" @click="action(s.row,'enable')">启用</el-button><el-button v-if="auth.hasPermission('resource:supplier:status')&&s.row.status==='ACTIVE'" link type="warning" @click="action(s.row,'pause')">暂停</el-button><el-button v-if="auth.hasPermission('resource:supplier:status')&&s.row.status!=='DISABLED'" link type="danger" @click="action(s.row,'disable')">停用</el-button></template></el-table-column></el-table><div class="pager"><el-pagination v-model:current-page="query.page" v-model:page-size="query.size" :total="total" layout="total, sizes, prev, pager, next" @change="load"/></div></el-card><el-dialog v-model="dialog" :title="editId?'编辑供应商':'新增供应商'" width="680px"><el-form label-width="105px"><el-form-item label="供应商编码" required><el-input v-model="form.supplierCode" :disabled="!!editId"/></el-form-item><el-form-item label="供应商名称" required><el-input v-model="form.supplierName"/></el-form-item><el-form-item label="联系人"><el-input v-model="form.contactName"/></el-form-item><el-form-item label="联系电话"><el-input v-model="form.contactPhone"/></el-form-item><el-form-item label="API地址" required><el-input v-model="form.apiEndpoint"/></el-form-item><el-form-item label="认证类型" required><el-input v-model="form.authTypeCode" placeholder="TOKEN / API_KEY / ..."/></el-form-item><el-form-item label="API账号"><el-input v-model="form.apiAccount"/></el-form-item><el-form-item label="密钥"><el-input v-model="form.secret" type="password" show-password :placeholder="editId?'留空表示不修改':'输入供应商密钥'"/></el-form-item><el-form-item label="获取模式"><el-select v-model="form.fetchMode"><el-option label="定时" value="SCHEDULED"/><el-option label="实时" value="REALTIME"/><el-option label="人工" value="MANUAL"/></el-select></el-form-item><el-form-item label="地区"><el-select v-model="form.regionCodes" multiple style="width:100%"><el-option v-for="x in options.regions" :key="x.item_code" :label="x.item_name" :value="x.item_code"/></el-select></el-form-item><el-form-item label="运营商"><el-select v-model="form.carrierCodes" multiple style="width:100%"><el-option v-for="x in options.carriers" :key="x.item_code" :label="x.item_name" :value="x.item_code"/></el-select></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template><style scoped>.page{display:grid;gap:16px}.head{display:flex;justify-content:space-between}.head h2{margin:0 0 6px}.head p{margin:0;color:#7b8494;max-width:850px}.filters{display:flex;gap:10px;margin-bottom:14px}.filters>*{max-width:280px}.pager{display:flex;justify-content:flex-end;margin-top:14px}</style>
